import unittest


def get_positive(l: list):
    return [e for e in l if e > 0]


class TestGetPositive(unittest.TestCase):

    def test_basic_positive_numbers(self):
        self.assertEqual(get_positive([1, 2, 3]), [1, 2, 3])

    def test_mixed_numbers(self):
        self.assertEqual(get_positive([-1, 2, -4, 5, 6]), [2, 5, 6])

    def test_all_negative(self):
        self.assertEqual(get_positive([-1, -2, -3]), [])

    def test_empty_list(self):
        self.assertEqual(get_positive([]), [])

    def test_zero_excluded(self):
        self.assertEqual(get_positive([0, 1, -1, 0]), [1])

    def test_floats(self):
        self.assertEqual(get_positive([-1.5, 2.5, 3.0]), [2.5, 3.0])

    def test_duplicates_preserved(self):
        self.assertEqual(get_positive([3, 3, -3, 3]), [3, 3, 3])

    def test_large_numbers(self):
        self.assertEqual(get_positive([-1000000, 1000000]), [1000000])

    def test_order_preserved(self):
        self.assertEqual(get_positive([5, -5, 1, -1, 9]), [5, 1, 9])


if __name__ == "__main__":
    unittest.main()
